package de.maxhenkel.corpse.entities;import dev.zomboid.remains.hygiene.HygieneChecks.*;public class CorpseEntity{public double x,y,z;public int tickCount;public Tag tag=new Tag();public boolean removed;public CorpseEntity(double x,double y,double z){this.x=x;this.y=y;this.z=z;}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}public boolean isRemoved(){return removed;}public Tag getPersistentData(){return tag;}public net.minecraft.core.BlockPos blockPosition(){return new net.minecraft.core.BlockPos((int)x,(int)y,(int)z);}}
